<?php
/**
 * GatewayPaymentSlipBlockTest class file.
 *
 * @package Serbian Addons for WooCommerce
 * @subpackage Tests
 */

namespace Oblak\WCSRB\Tests\Integration;

use Automattic\WooCommerce\Blocks\Payments\PaymentMethodRegistry;
use Oblak\WCSRB\Gateway\Gateway_Payment_Slip;
use Oblak\WCSRB\Gateway\Gateway_Payment_Slip_Block;
use Oblak\WCSRB\Services\Config;
use Oblak\WCSRB\Tests\Support\TestCase;

/**
 * Payment slip as a block checkout payment method.
 */
class GatewayPaymentSlipBlockTest extends TestCase {
    /**
     * Asset file fixture (the real one is generated by `npm run build:blocks`).
     */
    private const ASSET_FIXTURE = __DIR__ . '/../Support/fixtures/payment-slip.asset.php';

    /**
     * Forget the script a test registered.
     */
    public function tear_down(): void {
        \wp_deregister_script( Gateway_Payment_Slip_Block::SCRIPT_HANDLE );

        parent::tear_down();
    }

    public function test_registered_on_the_payment_method_registry(): void {
        $registry = new PaymentMethodRegistry();
        $registry->initialize();

        $this->assertInstanceOf( Gateway_Payment_Slip_Block::class, $registry->get_registered( 'wcsrb_payment_slip' ) );
    }

    public function test_registering_does_not_build_the_gateway(): void {
        // The registry is initialized on `init` for every request - building the gateway there is wasted work.
        $registry = new PaymentMethodRegistry();
        $registry->initialize();

        $prop = new \ReflectionProperty( Gateway_Payment_Slip_Block::class, 'gateway' );
        $prop->setAccessible( true );

        $this->assertNull( $prop->getValue( $registry->get_registered( 'wcsrb_payment_slip' ) ) );
    }

    public function test_uses_the_plugin_gateway_by_default(): void {
        $block = new Gateway_Payment_Slip_Block();

        $this->assertTrue( $block->is_active() );
        $this->assertSame( 'Payment Slip', $block->get_payment_method_data()['title'] );
    }

    public function test_active_when_enabled_and_valid(): void {
        $this->assertTrue( $this->block()->is_active() );
    }

    public function test_inactive_when_disabled(): void {
        $this->update_gateway_settings( array( 'enabled' => 'no' ) );

        $this->assertFalse( $this->block()->is_active() );
    }

    public function test_inactive_when_currency_is_not_rsd(): void {
        \update_option( 'woocommerce_currency', 'EUR' );

        $this->assertFalse( $this->block()->is_active() );
    }

    public function test_inactive_without_bank_account(): void {
        \update_option( 'woocommerce_store_bank_accounts', array() );

        $gateway = \xwp_app( 'wcsrb' )->make( Gateway_Payment_Slip::class, array( 'config' => new Config() ) );

        $this->assertFalse( $this->block( gateway: $gateway )->is_active() );
    }

    public function test_payment_method_data(): void {
        $this->assertSame(
            array(
                'description' => 'Pay by sending us money via wire transfer',
                'supports'    => array( 'products' ),
                'title'       => 'Payment Slip',
            ),
            $this->block()->get_payment_method_data(),
        );
    }

    public function test_script_registered_from_asset_file(): void {
        $block = $this->block( self::ASSET_FIXTURE );

        $this->assertSame( array( Gateway_Payment_Slip_Block::SCRIPT_HANDLE ), $block->get_payment_method_script_handles() );

        $script = \wp_scripts()->registered[ Gateway_Payment_Slip_Block::SCRIPT_HANDLE ];

        $this->assertStringEndsWith( '/serbian-addons-for-woocommerce/dist/blocks/payment-slip/index.js', $script->src );
        $this->assertSame( array( 'wc-blocks-registry', 'wc-settings', 'wp-i18n' ), $script->deps, 'Asset file deps; wp_set_script_translations() adds wp-i18n' );
        $this->assertSame( 'test-ver', $script->ver );
        $this->assertSame( 1, $script->extra['group'] ?? null, 'Loaded in the footer' );
        $this->assertSame( 'serbian-addons-for-woocommerce', $script->textdomain );
    }

    public function test_no_script_without_build(): void {
        $block = $this->block( '/nonexistent/index.asset.php' );

        $this->assertSame( array(), $block->get_payment_method_script_handles() );
        $this->assertFalse( \wp_script_is( Gateway_Payment_Slip_Block::SCRIPT_HANDLE, 'registered' ) );
    }

    /**
     * Make an initialized block integration.
     *
     * @param  string|null               $asset_file Asset file to read instead of the built one.
     * @param  Gateway_Payment_Slip|null $gateway    Gateway instance. Default the plugin's.
     * @return Gateway_Payment_Slip_Block
     */
    private function block( ?string $asset_file = null, ?Gateway_Payment_Slip $gateway = null ): Gateway_Payment_Slip_Block {
        $block = new Gateway_Payment_Slip_Block( $gateway ?? $this->gateway() );

        if ( null !== $asset_file ) {
            $prop = new \ReflectionProperty( Gateway_Payment_Slip_Block::class, 'asset_file' );
            $prop->setAccessible( true );
            $prop->setValue( $block, $asset_file );
        }

        $block->initialize();

        return $block;
    }
}
